package com.profa.teacher;
import com.profa.user.UserRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/teachers") public class TeacherController {final TeacherRepository repo;final UserRepository users;public TeacherController(TeacherRepository r,UserRepository u){repo=r;users=u;}
 @GetMapping public List<TeacherProfile> search(@RequestParam(required=false)String city,@RequestParam(required=false)Integer maxRate,@RequestParam(defaultValue="false")boolean verified){if(city!=null&&maxRate!=null)return repo.findByCityContainingIgnoreCaseAndHourlyRateLessThanEqual(city,maxRate);if(verified)return repo.findByVerifiedTrue();return repo.findAll();}
 @GetMapping("/me") @PreAuthorize("hasRole('TEACHER')") public TeacherProfile me(Authentication a){return repo.findByUserId(UUID.fromString(a.getName())).orElseThrow();}
 @PutMapping("/me") @PreAuthorize("hasRole('TEACHER')") public TeacherProfile update(Authentication a,@RequestBody TeacherProfile in){TeacherProfile p=repo.findByUserId(UUID.fromString(a.getName())).orElseThrow();p.setHeadline(in.getHeadline());p.setBio(in.getBio());p.setCity(in.getCity());p.setDistrict(in.getDistrict());p.setAddress(in.getAddress());p.setHourlyRate(in.getHourlyRate());p.setSalaryExpectation(in.getSalaryExpectation());p.setAvatarUrl(in.getAvatarUrl());p.setIntroVideoUrl(in.getIntroVideoUrl());p.setExperienceYears(in.getExperienceYears());p.setLanguages(in.getLanguages());p.setAvailabilityJson(in.getAvailabilityJson());return repo.save(p);}
}